<template><details class="diary-support"><summary>Soporte diario <span>{{totals.Atenciones}} atenciones</span><span>{{totals.CasosResueltos}} casos resueltos</span><span>{{totals.Seguimientos}} seguimientos</span><span>{{totals.Escalados}} escalados</span></summary><div class="diary-filters"><label>Desde<input type="date" v-model="from"></label><label>Hasta<input type="date" v-model="to"></label><button type="button" @click="load">Consultar atenciones</button></div><p class="diary-hint">Cuenta contactos registrados, no tareas concluidas. Los casos resueltos se cuentan una vez por tarea, empleado y día. El total del rango suma esos conteos diarios.</p><p v-if="error" class="diary-error">{{error}}</p><div class="diary-table-wrap"><table><thead><tr><th>Día</th><th>Empleado</th><th>Atenciones</th><th>Clientes</th><th>Casos atendidos</th><th>Soluciones registradas</th><th>Casos resueltos</th><th>Seguimiento</th><th>Escalados</th></tr></thead><tbody><tr v-for="d in days" :key="d.Dia+':'+d.Usuario"><td>{{d.Dia}}</td><td>{{d.Nombre}}</td><td>{{d.Atenciones}}</td><td>{{d.Clientes}}</td><td>{{d.Casos}}</td><td>{{d.Soluciones}}</td><td>{{d.CasosResueltos}}</td><td>{{d.Seguimientos}}</td><td>{{d.Escalados}}</td></tr><tr v-if="!days.length"><td colspan="9">Sin atenciones registradas para este rango.</td></tr></tbody></table></div></details></template>
<script>
import config from '@/store/config';import {limaInput} from '@/utils/diario';
export default {props:{vista:{default:'mia'}},data(){const day=limaInput().slice(0,10);return {from:day,to:day,days:[],error:''}},computed:{totals(){return this.days.reduce((s,d)=>{for(const k of Object.keys(s))s[k]+=Number(d[k]);return s},{Atenciones:0,CasosResueltos:0,Seguimientos:0,Escalados:0})}},watch:{vista(){this.load()}},mounted(){this.load();this.$root.$on('diario:attention',this.load)},beforeDestroy(){this.$root.$off('diario:attention',this.load)},methods:{async load(){try{const r=await this.axios.get(config.API+'diario/soporte/diario',{params:{desde:this.from,hasta:this.to,vista:this.vista},timeout:15000});this.days=r.data.dias;this.error=''}catch(e){this.error=e.response&&e.response.data.error||'No se pudo cargar el soporte diario.'}}}};
</script>
<style>.diary-support{background:white;border:1px solid #dce7ee;border-radius:11px;margin:10px 0;padding:12px 16px;color:#31566b}.diary-support>summary{font-weight:700;font-size:12px;cursor:pointer;line-height:2}.diary-support>summary>span{display:inline-block;font-weight:500;font-size:10px;margin-left:12px;color:#678b9d;background:#edf5f7;padding:1px 8px;border-radius:6px}.diary-support table{font-size:12px;width:100%;border-collapse:collapse}.diary-support td,.diary-support th{white-space:nowrap;padding:10px;border-bottom:1px solid #e5edf2;text-align:left}.diary-support th{background:#f1f6f8}</style>
